(* [comment removed for export] *)
Ltac is_uim t :=
  let w := eval vm_compute in (fetch_word usegs (Z_to_bv 64 t)) in
  lazymatch w with Some ?x => let b := eval vm_compute in (bv_unsigned x =? 3221229683) in
    lazymatch b with true => idtac end end.

Ltac land_norm K := repeat match type of K with
  | context [?x ≫ 2] => rewrite (Z.shiftr_div_pow2 x 2) in K by lia; change (2^2) with 4 in K
  | context [Z.land ?x 3] => change (Z.land x 3) with (Z.land x (Z.ones 2)) in K; rewrite (Z.land_ones x 2) in K by lia
  | context [Z.land ?x 7] => change (Z.land x 7) with (Z.land x (Z.ones 3)) in K; rewrite (Z.land_ones x 3) in K by lia
  end.
Ltac byte_fact b :=
  lazymatch b with
  | Znth ?k ?l => tryif (match goal with _ : 0 <= Znth k l < 256 |- _ => idtac end) then idtac
                  else (lazymatch goal with BY : Forall (fun c => 0 <= c < 256) l |- _ =>
                          pose proof (byte_Znth l k BY ltac:(lia)) end)
  | _ => idtac end.
Ltac jtnorm := repeat match goal with
  | |- context [Z.lor ((bv_unsigned (Z_to_bv 8 ?b1) ≪ 8) mod 18446744073709551616) (bv_unsigned (Z_to_bv 8 ?b0))] =>
      byte_fact b0; byte_fact b1; rewrite (x4_le16_lor b0 b1) by lia
  end.
Ltac jtnorm_in K := repeat match type of K with
  | context [Z.lor ((bv_unsigned (Z_to_bv 8 ?b1) ≪ 8) mod 18446744073709551616) (bv_unsigned (Z_to_bv 8 ?b0))] =>
      byte_fact b0; byte_fact b1; rewrite (x4_le16_lor b0 b1) in K by lia
  end;
  repeat match type of K with context [Znth ?k ?l] =>
    lazymatch goal with _ : 0 <= Znth k l < 256 |- _ => fail | _ => byte_fact (Znth k l) end end.
(* [comment removed for export] *)
Ltac kill K :=
  exfalso; rewrite ?unsigned_lit in K by lia; jtnorm_in K; rewrite ?zb_lxor_ones in K by lia; land_norm K;
  try (match type of K with context [Z.land ?x ?c] => pose proof (x4_land_le x c ltac:(lia)) end);
  repeat match type of K with context [?a <? ?b] => destruct (Z.ltb_spec a b) end;
  try (simpl Z.b2z in K; match type of K with context [Z.lxor ?a ?b] =>
         let v := eval vm_compute in (Z.lxor a b) in change (Z.lxor a b) with v in K end); lia.
(* [comment removed for export] *)
Ltac chk := lazymatch goal with
  | |- evt _ _ (MS _ _ (if _ then Z_to_bv 64 ?t else Z_to_bv 64 ?e) _ _ _ _) =>
      first [ is_uim t; let K := fresh "KC" in if_cases K; zify_cond K; [kill K | clear K]
            | is_uim e; let K := fresh "KC" in if_cases K; zify_cond K; [clear K | kill K] ]
  end.
Ltac showoff := lazymatch goal with
  | |- evt _ _ (MS _ _ (Z_to_bv 64 ?pc) _ _ _ _) => let d := eval vm_compute in (pc - 0x16e6c) in idtac "U+" d
  | |- evt _ _ (MS _ _ (if ?c then Z_to_bv 64 ?a else Z_to_bv 64 ?b) _ _ _ _) =>
      let d := eval vm_compute in (a - 0x16e6c) in let e := eval vm_compute in (b - 0x16e6c) in idtac "branch U+" d "/ U+" e; idtac c
  | |- evt _ _ (MS _ _ ?pc _ _ _ _) => idtac "pc:" pc end.
(* [comment removed for export] *)
Ltac pose_reads mg :=
  lazymatch goal with SRC : bytes_at usegs mg ?S0 (map (Z_to_bv 8) ?bs) |- _ =>
    let rd k := try (pose proof (src_rd usegs mg S0 bs k SRC ltac:(lia))) in rd 0; rd 1; rd 2; rd 3; rd 4; rd 5 end;
  try lazymatch goal with DTB : bytes_at usegs mg ?D [Z_to_bv 8 ?a; Z_to_bv 8 ?b; Z_to_bv 8 ?c; Z_to_bv 8 ?d] |- _ =>
    let R2 := fresh "RD" in
    pose proof (bytes_at_read usegs mg D _ 2 2 DTB ltac:(lia) ltac:(cbn; lia)) as R2;
    change (firstn 2 (skipn (Z.to_nat 2) [Z_to_bv 8 a; Z_to_bv 8 b; Z_to_bv 8 c; Z_to_bv 8 d])) with [Z_to_bv 8 c; Z_to_bv 8 d] in R2;
    rewrite <- (le2_two_bytes c d) in R2 by lia
  end.
Ltac rd_refresh :=
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mg _) =>
  tryif (match goal with _ : ov_read_bytes usegs mg (Z_to_bv 64 (_ + 5)) 1 = Some _,
                         _ : ov_read_bytes usegs mg _ 2 = Some _ |- _ => idtac end) then idtac
  else (repeat match goal with H : ov_read_bytes usegs _ _ _ = Some _ |- _ => clear H end; pose_reads mg) end.
Ltac kill_ctx :=
  first [ match goal with
          | K : (_ < _)%Z |- _ => kill K
          | K : (_ <= _)%Z |- _ => kill K
          | K : (_ = _ :> Z) |- _ => kill K
          | K : (_ <> _ :> Z) |- _ => kill K
          end
        | showoff; match goal with K : (_ < _)%Z |- _ => idtac "LAST" K; let t := type of K in idtac t end; fail 1 "uim reached" ].
(* [comment removed for export] *)
Ltac run := repeat (lazymatch goal with
    | |- evt _ _ (MS _ _ (if _ then _ else _) _ _ _ _) => chk
    | |- evt _ _ (MS _ _ (Z_to_bv 64 0x1a500) _ _ _ _) => fail
    | |- evt _ _ (MS _ _ (Z_to_bv 64 0x1826c) _ _ _ _) => fail
    | |- evt _ _ (MS _ _ (Z_to_bv 64 0x18268) _ _ _ _) => fail
    | |- evt _ _ (MS _ _ (Z_to_bv 64 0x17ad0) _ _ _ _) => fail
    | |- evt _ _ (MS _ _ (Z_to_bv 64 0x18cfc) _ _ _ _) => fail
    | |- evt _ _ (MS _ _ (Z_to_bv 64 ?p) _ _ _ _) => tryif is_uim p then kill_ctx else (rd_refresh; zstep; jtnorm)
    end).
(* [comment removed for export] *)
Ltac peel H :=
  lazymatch type of H with rw_cells ?sg ?m ?A (?c :: ?rest) =>
    let H1 := fresh "FP" in let H2 := fresh "FQ" in
    destruct (x4_rw_cells_cons sg m A c rest H) as [H1 H2]; clear H;
    cbn [cells_size csize Nat.add] in H2;
    lazymatch type of H2 with rw_cells _ _ (bv_unsigned ?s + ?a + Z.of_nat ?k) _ =>
      let v := eval vm_compute in (a + Z.of_nat k) in
      replace (bv_unsigned s + a + Z.of_nat k) with (bv_unsigned s + v) in H2 by lia end;
    rename H2 into H
  end.
Ltac notchk := lazymatch goal with
  | |- evt _ _ (MS _ _ (if _ then Z_to_bv 64 ?t else Z_to_bv 64 ?e) _ _ _ _) =>
      first [ is_uim t; fail 1 | is_uim e; fail 1 | idtac ] end.
Ltac x4_cells_eq := repeat match goal with
  | |- (_ :: _) = (_ :: _) => f_equal
  | |- C8 _ = C8 _ => f_equal
  | |- C4 _ = C4 _ => f_equal
  | |- Z_to_bv 64 _ = Z_to_bv 64 _ => f_equal
  end; try reflexivity; try lia.
Ltac x4_cb8_at H k :=
  lazymatch type of H with rw_cells _ ?m ?A ?cs =>
    let pre := eval cbn [firstn] in (firstn k cs) in
    let post := eval cbn [skipn] in (skipn (S k) cs) in
    let c := eval cbn [nth] in (nth k cs (C1 (Z_to_bv 8 0))) in
    lazymatch c with Cells.CB 8 ?b =>
      let v := fresh "v" in let H' := fresh "H" in
      destruct (x4_cb8_c8 m A pre b post H) as (v & H'); clear H; cbn [app] in H'; rename H' into H end end.
